function sig(x,w,h){var d=x.getImageData(0,0,w,h).data,s=0,st=4*Math.max(1,Math.floor(d.length/4/3000));for(var i=0;i<d.length;i+=st)s=(s*31+d[i]+d[i+1]*3+d[i+2]*7)|0;return s}
function snap(){var c=biggest();if(!c||!c.width)return null;try{var w=Math.min(640,c.width),h=Math.max(1,Math.round(c.height*w/c.width)),s=document.createElement('canvas');s.width=w;s.height=h;var x=s.getContext('2d');x.fillStyle=getComputedStyle(document.documentElement).getPropertyValue('--bg')||'#fff';x.fillRect(0,0,w,h);x.drawImage(c,0,0,w,h);return{url:s.toDataURL('image/jpeg',0.72),sig:sig(x,w,h)}}catch(e){return null}}
var A=null,slow=!!document.querySelector('script[type="text/babel"]');setTimeout(function(){A=snap()},slow?3600:1100);
